// Builds mobile/src/legal/legalText.generated.ts from docs/PRIVACY-POLICY.md and docs/TERMS.md, so the
// text shown in the app is always the published text. Run: node scripts/build-legal.mjs
// `--check` exits with an error when the generated file is out of date (a test runs it).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT = path.join(root, "mobile", "src", "legal", "legalText.generated.ts");

const clean = (text) => text.replace(/\*\*/g, "").replace(/`/g, "");

export function parse(markdown) {
  const lines = markdown.replace(/\r\n/g, "\n").split("\n");
  let title = "";
  let updated = "";
  const sections = [];
  let current = null;
  let para = [];
  let bullet = null;
  const flushPara = () => {
    if (para.length > 0 && current) current.blocks.push(clean(para.join(" ").trim()));
    para = [];
  };
  const flushBullet = () => {
    if (bullet !== null && current) current.blocks.push("• " + clean(bullet.trim()));
    bullet = null;
  };
  for (const line of lines) {
    if (line.startsWith("# ")) {
      title = clean(line.slice(2)).replace(/\s*\(draft for legal review\)\s*/i, "").trim();
    } else if (line.startsWith("## ")) {
      flushBullet();
      flushPara();
      current = { heading: clean(line.slice(3).trim()), blocks: [] };
      sections.push(current);
    } else if (line.startsWith("- ")) {
      flushBullet();
      flushPara();
      bullet = line.slice(2);
    } else if (line.startsWith("  ") && bullet !== null) {
      bullet += " " + line.trim();
    } else if (line.trim() === "") {
      flushBullet();
      flushPara();
    } else if (current) {
      flushBullet();
      para.push(line.trim());
    } else {
      const m = line.match(/Last updated: ([0-9-]+)/);
      if (m) updated = m[1];
    }
  }
  flushBullet();
  flushPara();
  return { title, updated, sections };
}

export function build() {
  const docs = {
    privacy: parse(fs.readFileSync(path.join(root, "docs", "PRIVACY-POLICY.md"), "utf8")),
    terms: parse(fs.readFileSync(path.join(root, "docs", "TERMS.md"), "utf8")),
  };
  return (
    "// GENERATED by scripts/build-legal.mjs from docs/PRIVACY-POLICY.md and docs/TERMS.md. Do not edit.\n" +
    "export interface LegalSection {\n  heading: string;\n  blocks: string[];\n}\n" +
    "export interface LegalDocument {\n  title: string;\n  updated: string;\n  sections: LegalSection[];\n}\n\n" +
    `export const privacyPolicy: LegalDocument = ${JSON.stringify(docs.privacy, null, 2)};\n\n` +
    `export const termsAndConditions: LegalDocument = ${JSON.stringify(docs.terms, null, 2)};\n`
  );
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const text = build();
  if (process.argv.includes("--check")) {
    const existing = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
    if (existing !== text) {
      console.error("legalText.generated.ts is out of date: run node scripts/build-legal.mjs");
      process.exit(1);
    }
  } else {
    fs.mkdirSync(path.dirname(OUT), { recursive: true });
    fs.writeFileSync(OUT, text);
    console.log("legal: wrote " + path.relative(root, OUT));
  }
}
